package cn.adc.duration;
import cn.adc.shared.audit.AuditDocuments;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DurationPolicyTest {
 @Test void nameCharacterLimitMatchesPostgreSqlCharactersNotUtf16Units(){var n=AuditDocuments.JSON.createObjectNode().put("projectName","\uD83D\uDE00".repeat(200)).put("durationMinutes",30);assertDoesNotThrow(()->DurationPolicyService.validateDraft(n));n.put("projectName","\uD83D\uDE00".repeat(201));assertThrows(IllegalArgumentException.class,()->DurationPolicyService.validateDraft(n));}
 @Test void strictMinutesAndNameHaveNoDefaultOrRounding(){assertThrows(IllegalArgumentException.class,()->DurationPolicyService.validateDraft(AuditDocuments.parse("{\"projectName\":\"x\",\"durationMinutes\":1.0}")));assertThrows(IllegalArgumentException.class,()->DurationPolicyService.validateDraft(AuditDocuments.parse("{\"projectName\":\"x\"}")));assertThrows(IllegalArgumentException.class,()->DurationPolicyService.validateDraft(AuditDocuments.parse("{\"projectName\":\"  \",\"durationMinutes\":30}")));assertDoesNotThrow(()->DurationPolicyService.validateDraft(AuditDocuments.parse("{\"projectName\":\"SYNTHETIC\",\"durationMinutes\":2147483647}")));}
 @Test void timeOrScheduleOnlyKeepsOriginalPublishedBasis(){var old=new DurationPolicyService.Basis(1,1,30);var current=new DurationPolicyService.Basis(1,2,60);assertEquals(old,DurationPolicyService.selectBasis(DurationPolicyService.ChangeKind.TIME_ONLY,old,current));assertEquals(old,DurationPolicyService.selectBasis(DurationPolicyService.ChangeKind.SCHEDULE_ONLY,old,current));assertEquals(current,DurationPolicyService.selectBasis(DurationPolicyService.ChangeKind.FIRST,null,current));assertEquals(current,DurationPolicyService.selectBasis(DurationPolicyService.ChangeKind.PROJECT_CHANGED,old,current));assertThrows(IllegalArgumentException.class,()->DurationPolicyService.selectBasis(DurationPolicyService.ChangeKind.FIRST,null,null));}
}
